typedef unsigned int u_int;
typedef unsigned long long u_long;

struct nglTexture
{
  u_int TexStreamPos[2];
  unsigned short Width, Height;
};

struct nglQuadVertex
{
  float X, Y;
  float U, V;
  u_int Color;
};

struct nglQuad
{
  nglQuadVertex Verts[4];
  float Z;
  u_int MapFlags;
  u_int BlendMode;
  u_int BlendModeConstant;
  nglTexture* Tex;
};

struct nglScene
{
  void* Parent;
  void* NextSibling;
  void* FirstChild;
  void* LastChild;
  nglTexture* RenderTarget;
};

extern nglScene* nglCurScene;
extern u_int nglGifRegCount;
extern unsigned char nglGifRegIdx[128];
extern u_long nglGifRegVal[128];

bool nglVif1AddTextureStreaming( u_int*& Packet, nglTexture** Textures, int NTextures );
void nglVif1AddQuadMaterial( nglQuad* Quad );
void nglVif1AddQuadVerts( nglQuad* Quad );

inline int nglFTOI( float input )
{
  register float output;
  __asm__ volatile ("cvt.w.s %0, %1" : "=f" (output) : "f" (input) );
  return (int&)output;
}

inline bool nglVif1AddSingleTextureStreaming( u_int*& Packet, nglTexture* Tex )
{
  return nglVif1AddTextureStreaming( Packet, &Tex, 1 );
}

inline void nglVif1StartDirectGifAD()
{
  nglGifRegCount = 0;
}

inline void nglVif1EndDirectGifAD( u_int*& Packet )
{
  while ( (u_int)( Packet + 1 ) & 15 ) *(Packet++) = 0;
  *(Packet++) = ( ( nglGifRegCount + 1 ) & 0xffff ) | ( 0x50 << 24 );

  u_long* TagPtr = (u_long*)Packet;
  TagPtr[0] = (u_long)nglGifRegCount | ( (u_long)1 << 15 ) | ( (u_long)1 << 60 );
  TagPtr[1] = 0xE;
  TagPtr += 2;

  for ( u_int i = 0; i < nglGifRegCount; i++ )
  {
    TagPtr[0] = nglGifRegVal[i];
    TagPtr[1] = nglGifRegIdx[i];
    TagPtr += 2;
  }
  Packet = (u_int*)TagPtr;
}

void nglVif1RenderQuad( u_int*& Packet, nglQuad* Quad )
{
  if ( 0 )
    return;

  for ( int j = 0; j < 4; j++ )
  {
    nglQuadVertex* Vert = &Quad->Verts[j];
    int x = nglFTOI( ( Vert->X + 2048 - ( nglCurScene->RenderTarget->Width / 2 ) ) * 16 );
    int y = nglFTOI( ( Vert->Y + 2048 - ( nglCurScene->RenderTarget->Height / 2 ) ) * 16 );
    if ( x < 0 || x > 4095 * 16 || y < 0 || y > 4095 * 16 )
      return;
  }

  if ( Quad->Tex )
    nglVif1AddSingleTextureStreaming( Packet, Quad->Tex );

  nglVif1StartDirectGifAD();

  nglVif1AddQuadMaterial( Quad );
  nglVif1AddQuadVerts( Quad );

  nglVif1EndDirectGifAD( Packet );
}
